"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[79284],{79284:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-traffic-officers-night.png\\"\\n          title=\\"The Traffic Officer\'s Night\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"Baum\\"\\n          publishedDate=\\"2010-01-15\\"\\n          isbn=\\"9788958830764\\"\\n          rating=3.5\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\nThis work uses the extremely common subject of traffic violations as a microscope to reveal human selfishness, responsibility, and the unfillable gap between legal justice and moral justice.  \\n<br>\\nThis work consists of six short stories and shows the process of how a ```minor traffic violation``` is amplified into an irreversible tragedy.  \\n<br>\\nIn particular, the first story, <mark>Angel\'s Ears</mark>, shows how a case is distorted by social prejudice.  \\n<br>\\nThe self-justification of ```everyone does it``` is the psychological root of all tragedies.  \\nIt\'s a work that acts as a warning light for all of us.  "}')}}]);